import struct
import hashlib
import os
import sqlite3
from flask import Flask, request, jsonify, g
from functools import wraps
import secrets

app = Flask(__name__)
DATABASE = ':memory:'
SECRET_HMAC_KEY = os.environ.get('HMAC_SECRET', secrets.token_hex(32))

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
        _init_db(g.db)
    return g.db

def _init_db(db):
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        base_permission INTEGER DEFAULT 100
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS groups (
        id INTEGER PRIMARY KEY,
        name TEXT NOT NULL,
        permission_modifier INTEGER DEFAULT 0
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS user_groups (
        user_id INTEGER,
        group_id INTEGER,
        FOREIGN KEY(user_id) REFERENCES users(id),
        FOREIGN KEY(group_id) REFERENCES groups(id)
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS resources (
        id INTEGER PRIMARY KEY,
        name TEXT NOT NULL,
        content TEXT NOT NULL,
        required_level INTEGER NOT NULL
    )''')
    db.commit()

def _compute_hmac(message: str) -> str:
    return hashlib.sha256((SECRET_HMAC_KEY + message).encode()).hexdigest()

def _create_token(user_id: int, username: str) -> str:
    payload = f"{user_id}:{username}"
    sig = _compute_hmac(payload)
    return f"{payload}:{sig}"

def _verify_token(token: str):
    parts = token.rsplit(':', 1)
    if len(parts) != 2:
        return None
    payload, sig = parts
    if _compute_hmac(payload) != sig:
        return None
    user_parts = payload.split(':', 1)
    if len(user_parts) != 2:
        return None
    try:
        return {'user_id': int(user_parts[0]), 'username': user_parts[1]}
    except ValueError:
        return None

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth = request.headers.get('Authorization', '')
        if not auth.startswith('Bearer '):
            return jsonify({'error': 'unauthorized'}), 401
        token_data = _verify_token(auth[7:])
        if not token_data:
            return jsonify({'error': 'invalid_token'}), 401
        g.user = token_data
        return f(*args, **kwargs)
    return decorated

def _compute_effective_permission(user_id: int) -> int:
    """Compute effective permission level by combining base permission
    with all group modifiers. Result is packed as signed 32-bit integer
    to maintain compatibility with legacy permission system."""
    db = get_db()
    user = db.execute('SELECT base_permission FROM users WHERE id = ?', (user_id,)).fetchone()
    if not user:
        return 0
    base = user['base_permission']
    groups = db.execute(
        'SELECT g.permission_modifier FROM groups g '
        'JOIN user_groups ug ON g.id = ug.group_id '
        'WHERE ug.user_id = ?', (user_id,)
    ).fetchall()
    total_modifier = sum(row['permission_modifier'] for row in groups)
    raw_level = base + total_modifier
    # Pack as signed 32-bit integer for legacy compatibility
    packed = struct.pack('>i', raw_level & 0xFFFFFFFF)
    effective = struct.unpack('>i', packed)[0]
    return effective

def _check_access(effective_level: int, required_level: int) -> bool:
    """Check if user's effective permission meets the required level.
    Administrative resources require level > 2147483000.
    Standard access: effective_level must be greater than required_level."""
    if required_level > 2147483000:
        # Admin resources: any negative effective_level grants access
        # (legacy: negative values indicate overflow from high-privilege accumulation)
        return effective_level < 0 or effective_level > required_level
    return effective_level > required_level

@app.route('/api/auth/register', methods=['POST'])
def register():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'missing_fields'}), 400
    username = data['username']
    password = data['password']
    if not isinstance(username, str) or not isinstance(password, str):
        return jsonify({'error': 'invalid_types'}), 400
    if len(username) > 64 or len(password) > 128:
        return jsonify({'error': 'too_long'}), 400
    pw_hash = hashlib.sha256(password.encode()).hexdigest()
    db = get_db()
    try:
        cursor = db.execute(
            'INSERT INTO users (username, password_hash) VALUES (?, ?)',
            (username, pw_hash)
        )
        db.commit()
        user_id = cursor.lastrowid
        token = _create_token(user_id, username)
        return jsonify({'token': token, 'user_id': user_id}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'username_taken'}), 409

@app.route('/api/auth/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'missing_fields'}), 400
    username = data['username']
    password = data['password']
    pw_hash = hashlib.sha256(password.encode()).hexdigest()
    db = get_db()
    user = db.execute(
        'SELECT id, username FROM users WHERE username = ? AND password_hash = ?',
        (username, pw_hash)
    ).fetchone()
    if not user:
        return jsonify({'error': 'invalid_credentials'}), 401
    token = _create_token(user['id'], user['username'])
    return jsonify({'token': token}), 200

@app.route('/api/groups/join', methods=['POST'])
@require_auth
def join_group():
    data = request.get_json()
    if not data or 'group_id' not in data:
        return jsonify({'error': 'missing_group_id'}), 400
    group_id = data['group_id']
    if not isinstance(group_id, int):
        return jsonify({'error': 'invalid_group_id'}), 400
    db = get_db()
    group = db.execute('SELECT id FROM groups WHERE id = ?', (group_id,)).fetchone()
    if not group:
        return jsonify({'error': 'group_not_found'}), 404
    existing = db.execute(
        'SELECT 1 FROM user_groups WHERE user_id = ? AND group_id = ?',
        (g.user['user_id'], group_id)
    ).fetchone()
    if existing:
        return jsonify({'error': 'already_member'}), 409
    db.execute(
        'INSERT INTO user_groups (user_id, group_id) VALUES (?, ?)',
        (g.user['user_id'], group_id)
    )
    db.commit()
    return jsonify({'status': 'joined'}), 200

@app.route('/api/resources/<int:resource_id>', methods=['GET'])
@require_auth
def get_resource(resource_id):
    db = get_db()
    resource = db.execute(
        'SELECT * FROM resources WHERE id = ?', (resource_id,)
    ).fetchone()
    if not resource:
        return jsonify({'error': 'not_found'}), 404
    effective = _compute_effective_permission(g.user['user_id'])
    required = resource['required_level']
    if not _check_access(effective, required):
        return jsonify({'error': 'insufficient_permission', 'your_level': effective, 'required': required}), 403
    return jsonify({'name': resource['name'], 'content': resource['content']}), 200

